//! Long strings read back whole and are matched by q.

use andromeda_test_suite::{
    attribute_matcher::any_attribute,
    broker,
    entity_matcher::has_attribute,
    identity_matcher::has_id,
    namespace::Namespace,
    outcome::Done,
};
use googletest::prelude::*;
use ngsi_ld::{
    http::headers::Accept,
    model::{Attribute, AttributeName, Entity, NgsiLdMediaType, Property},
    query::{Locality, q},
};

/// Pins: An Entity whose description holds 6,000 characters, `atLimit` 2,704 octets of two-octet characters and
/// `pastLimit` one octet more reads each back whole and q equality selects it by each; Replace Attribute with
/// "short" and a Partial Attribute Update with another 6,000 characters answer 204 and each value reads back whole
/// Clause: 5.6.1, 5.7.1, 4.9, 5.6.19, 5.6.4
#[gtest]
#[tokio::test]
async fn n_ent_cre_9037_long_strings_read_back_whole_and_are_matched_by_q() -> Result<()> {
    let namespace = Namespace::fresh();
    let broker = broker::front()?;
    let building_long_text_id = namespace.urn("Building", "long-text")?;
    let building_type = namespace.entity_type("Building")?;
    let building_long_text = Entity::builder()
        .id(building_long_text_id.clone())
        .entity_type(building_type.clone())
        .property("description", "")
        .property("atLimit", "é".repeat(1352).as_str())
        .property("pastLimit", format!("{}a", "é".repeat(1352)).as_str())
        .build()?;
    broker.entities().create(&building_long_text).send().await?.done()?;
    let retrieved = broker
        .with_accept(Accept::new(NgsiLdMediaType::Json))
        .entities()
        .retrieve(&building_long_text_id)
        .send()
        .await?;
    let entity = retrieved.body();
    expect_that!(entity, has_attribute("description", any_attribute().value("")));
    expect_that!(entity, has_attribute("atLimit", any_attribute().value("é".repeat(1352).as_str())));
    expect_that!(
        entity,
        has_attribute("pastLimit", any_attribute().value(format!("{}a", "é".repeat(1352)).as_str()))
    );
    let page = broker.with_accept(Accept::new(NgsiLdMediaType::Json)).entities().query().entity_type(&building_type).locality(Locality::Local).q(q::attr("description").eq("")).send().await?;
    expect_that!(page.items(), len(eq(1)));
    expect_that!(page.items(), contains(has_id(&building_long_text_id)));
    let page_2 = broker
        .with_accept(Accept::new(NgsiLdMediaType::Json))
        .entities()
        .query()
        .entity_type(&building_type)
        .locality(Locality::Local)
        .q(q::attr("atLimit").eq("é".repeat(1352).as_str()))
        .send()
        .await?;
    expect_that!(page_2.items(), len(eq(1)));
    expect_that!(page_2.items(), contains(has_id(&building_long_text_id)));
    let page_3 = broker
        .with_accept(Accept::new(NgsiLdMediaType::Json))
        .entities()
        .query()
        .entity_type(&building_type)
        .locality(Locality::Local)
        .q(q::attr("pastLimit").eq(format!("{}a", "é".repeat(1352)).as_str()))
        .send()
        .await?;
    expect_that!(page_3.items(), len(eq(1)));
    expect_that!(page_3.items(), contains(has_id(&building_long_text_id)));
    let attribute = Attribute::from(Property::builder("short").build()?);
    broker
        .entities()
        .replace_attribute(&building_long_text_id, &"description".parse::<AttributeName>()?, &attribute)
        .send()
        .await?
        .done()?;
    let retrieved_2 = broker
        .with_accept(Accept::new(NgsiLdMediaType::Json))
        .entities()
        .retrieve(&building_long_text_id)
        .send()
        .await?;
    let entity_2 = retrieved_2.body();
    expect_that!(entity_2, has_attribute("description", any_attribute().value("short")));
    let patch = Attribute::from(Property::builder("").build()?).into_patch();
    broker
        .entities()
        .update_attribute(&building_long_text_id, &"description".parse::<AttributeName>()?, patch)
        .send()
        .await?
        .done()?;
    let retrieved_3 = broker
        .with_accept(Accept::new(NgsiLdMediaType::Json))
        .entities()
        .retrieve(&building_long_text_id)
        .send()
        .await?;
    let entity_3 = retrieved_3.body();
    expect_that!(entity_3, has_attribute("description", any_attribute().value("")));
    Ok(())
}
